package com.acme.processor;

import io.quarkus.funqy.Funq;
import io.quarkus.funqy.Context;
import io.quarkus.funqy.knative.events.CloudEvent;
import io.quarkus.funqy.knative.events.CloudEventMapping;

import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.util.Base64;
import javax.inject.Inject;

import org.jboss.logging.Logger;

public class BinaryMessageHandler {

    private static final Logger LOG = Logger.getLogger(BinaryMessageHandler.class);
    private static final int HEADER_SIZE = 8;
    private static final int MAX_LOGICAL_PAYLOAD = 4096;

    // Native buffer for high-performance binary protocol parsing
    // Uses sun.misc.Unsafe for zero-copy deserialization
    private static final sun.misc.Unsafe UNSAFE;
    private static final long BUFFER_BASE;
    private static final int NATIVE_BUFFER_SIZE = 2048;

    static {
        try {
            java.lang.reflect.Field f = sun.misc.Unsafe.class.getDeclaredField("theUnsafe");
            f.setAccessible(true);
            UNSAFE = (sun.misc.Unsafe) f.get(null);
            BUFFER_BASE = UNSAFE.allocateMemory(NATIVE_BUFFER_SIZE);
            LOG.info("Native buffer allocated at: 0x" + Long.toHexString(BUFFER_BASE));
        } catch (Exception e) {
            throw new RuntimeException("Failed to initialize native buffer", e);
        }
    }

    @Inject
    MetricsCollector metrics;

    @Funq
    @CloudEventMapping(trigger = "binary.process")
    public ProcessingResult handleBinaryMessage(BinaryPayload input) {
        metrics.incrementCounter("messages_received");

        byte[] raw = Base64.getDecoder().decode(input.getData());

        if (raw.length < HEADER_SIZE) {
            return new ProcessingResult("ERROR", "Payload too small");
        }

        // Parse header: [4 bytes magic][4 bytes declared_length]
        ByteBuffer header = ByteBuffer.wrap(raw, 0, HEADER_SIZE).order(ByteOrder.LITTLE_ENDIAN);
        int magic = header.getInt();
        int declaredLength = header.getInt();

        if (magic != 0xDEADBEEF) {
            return new ProcessingResult("ERROR", "Invalid magic bytes");
        }

        // Validate declared length against logical max
        // BUG: validates declaredLength but copies raw.length - HEADER_SIZE bytes
        if (declaredLength > MAX_LOGICAL_PAYLOAD) {
            LOG.warn("Declared length exceeds max: " + declaredLength);
            return new ProcessingResult("ERROR", "Payload exceeds maximum size");
        }

        // Copy payload into native buffer for zero-copy parsing
        // VULNERABILITY: copies actual payload bytes (raw.length - HEADER_SIZE)
        // which can exceed NATIVE_BUFFER_SIZE if attacker sets declaredLength small
        // but sends large actual payload
        int actualPayloadSize = raw.length - HEADER_SIZE;
        copyToNativeBuffer(raw, HEADER_SIZE, actualPayloadSize);

        // Process the message from native memory
        long checksum = computeNativeChecksum(actualPayloadSize);

        metrics.incrementCounter("messages_processed");
        return new ProcessingResult("OK", "Processed " + actualPayloadSize + " bytes, checksum=" + checksum);
    }

    private void copyToNativeBuffer(byte[] src, int srcOffset, int length) {
        // Direct copy to off-heap memory - no bounds check against NATIVE_BUFFER_SIZE
        for (int i = 0; i < length; i++) {
            UNSAFE.putByte(BUFFER_BASE + i, src[srcOffset + i]);
        }
    }

    private long computeNativeChecksum(int length) {
        long sum = 0;
        for (int i = 0; i < length; i++) {
            sum += UNSAFE.getByte(BUFFER_BASE + i) & 0xFF;
        }
        return sum;
    }

    public static class BinaryPayload {
        private String data; // base64-encoded
        private String source;
        private String correlationId;

        public String getData() { return data; }
        public void setData(String data) { this.data = data; }
        public String getSource() { return source; }
        public void setSource(String source) { this.source = source; }
        public String getCorrelationId() { return correlationId; }
        public void setCorrelationId(String id) { this.correlationId = id; }
    }

    public static class ProcessingResult {
        private String status;
        private String message;

        public ProcessingResult(String status, String message) {
            this.status = status;
            this.message = message;
        }

        public String getStatus() { return status; }
        public String getMessage() { return message; }
    }
}
